    let tensor = tensor.view();
    let (axis, include_initial) = prepare_cumulative_args(tensor.layout().ndim(), args.into())?;
    let (storage, layout) =
        tensor.device().cumulative_sum_dtype(tensor.raw(), tensor.layout(), axis, include_initial)?;
