pub trait TensorSumBoolAPI<B, D>
where
    D: DimAPI,
    B: DeviceAPI<bool> + DeviceAPI<usize> + OpSumBoolAPI<D>,
{
    fn sum_all_f(&self) -> Result<usize>;
    fn sum_all(&self) -> usize {
        self.sum_all_f().rstsr_unwrap()
    }
    fn sum_f(&self) -> Result<usize> {
        self.sum_all_f()
    }
    fn sum(&self) -> usize {
        self.sum_f().rstsr_unwrap()
    }
    fn sum_axes_f(&self, axes: impl TryInto<AxesIndex<isize>, Error: Into<Error>>) -> Result<Tensor<usize, B, IxD>>;
    fn sum_axes(&self, axes: impl TryInto<AxesIndex<isize>, Error: Into<Error>>) -> Tensor<usize, B, IxD> {
        self.sum_axes_f(axes).rstsr_unwrap()
    }
    fn sum_with_args_f(&self, args: impl Into<ReduceArgs>) -> Result<Tensor<usize, B, IxD>>;
    fn sum_with_args(&self, args: impl Into<ReduceArgs>) -> Tensor<usize, B, IxD> {
        self.sum_with_args_f(args).rstsr_unwrap()
    }
}

impl<R, B, D> TensorSumBoolAPI<B, D> for TensorAny<R, bool, B, D>
where
    R: DataAPI<Data = <B as DeviceRawAPI<bool>>::Raw>,
    D: DimAPI,
    B: DeviceAPI<bool> + DeviceAPI<usize> + OpSumBoolAPI<D> + DeviceCreationAnyAPI<usize>,
{
    fn sum_all_f(&self) -> Result<usize> {
        self.device().sum_all(self.raw(), self.layout())
    }

    fn sum_axes_f(&self, axes: impl TryInto<AxesIndex<isize>, Error: Into<Error>>) -> Result<Tensor<usize, B, IxD>> {
        let axes = axes.try_into().map_err(Into::into)?;

        match axes {
            AxesIndex::None => {
                // special case for summing all axes
                let sum = self.device().sum_all(self.raw(), self.layout())?;
                let storage = self.device().outof_cpu_vec(vec![sum])?;
                let layout = Layout::new(vec![], vec![], 0)?;
                Tensor::new_f(storage, layout)
            },
            _ => {
                let (storage, layout) = self.device().sum_axes(self.raw(), self.layout(), axes.as_ref())?;
                Tensor::new_f(storage, layout)
            },
        }
    }

    fn sum_with_args_f(&self, args: impl Into<ReduceArgs>) -> Result<Tensor<usize, B, IxD>> {
        let ReduceArgs { axes, keepdims } = args.into();
        let tensor = self.view();
        reduce_dispatch_output!(tensor, sum_all, sum_axes, axes, keepdims)
    }
}

